import{_ as l,o as n,c as e,ag as i}from"./chunks/framework.PVHj0As1.js";const t="/pub-blog/assets/image-20260310100232053.DNFPqlZa.png",o="/pub-blog/assets/image-20260310100331112.cyBQIKyR.png",s="/pub-blog/assets/image-20260310100437311.YxFMFiP5.png",p="/pub-blog/assets/image-20260310100522855.DuAXXli6.png",r="/pub-blog/assets/image-20260310100553812.jczLJ7lg.png",h="/pub-blog/assets/image-20260310100803670.BsQcBB16.png",c="/pub-blog/assets/image-20260310101128909.rFI5p8UA.png",u="/pub-blog/assets/image-20260310101220267.fEzpeMEj.png",g="/pub-blog/assets/image-20260310101414065.bYcpFYQi.png",k="/pub-blog/assets/image-20260310101801451.CIQ39h8Q.png",m="/pub-blog/assets/image-20260310101949649.BoKpJMOi.png",b="/pub-blog/assets/image-20260310102040615.hhQdUtpW.png",x=JSON.parse('{"title":"用 OpenClaw 实现小红书自动发帖","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/用 OpenClaw 实现小红书自动发帖/用OpenClaw实现小红书自动发帖.md","filePath":"AI人工智能/用 OpenClaw 实现小红书自动发帖/用OpenClaw实现小红书自动发帖.md","lastUpdated":1773115531000,"__rawMarkdown":"# 用 OpenClaw 实现小红书自动发帖\\n\\n本文将详细介绍如何使用 OpenClaw 的 **skill**功能实现小红书自动发帖，帮助内容创作者提高发布效率，实现自动化内容运营。\\n\\n## 什么是 MCP 服务对接\\n\\nMCP（Model Control Protocol）服务对接是 OpenClaw 支持的一种自动化操作方式，通过平台提供的官方 MCP 接口进行交互。与托管浏览器方式不同，MCP 方式具有以下优势：\\n\\n- **配置更简单**：无需手动配置浏览器插件和 Token\\n- **稳定性更高**：官方接口通常更加稳定可靠\\n- **功能更完整**：MCP 服务通常提供更丰富的操作能力\\n- **安全性更好**：符合平台规范，不易触发风控\\n\\n小红书平台已经提供了相应的 MCP 服务，并且在 ClawHub（OpenClaw 官方 Skill 市场）上已有公开的 Skill，用户可以方便地使用。\\n\\n## 准备工作\\n\\n在使用前，请确保已完成以下准备工作：\\n\\n1. 已完成 OpenClaw 的安装与基础配置\\n2. 拥有一个有效的小红书账号\\n3. 确保网络连接正常，能够访问小红书平台\\n\\n## 详细操作流程\\n\\n### 第一步：访问 ClawHub 网站\\n\\n打开浏览器，访问 ClawHub 官方网站：https://clawhub.ai\\n\\nClawHub 是 OpenClaw 官方用来管理 Skill 的网站，用户可以在这里找到很多实用的 Skill，也可以发布自己开发的 Skill。\\n\\n![](assets/image-20260310100232053.png)\\n\\n### 第二步：搜索小红书 Skill\\n\\n点击 ClawHub 网站顶部导航栏的\\"Search\\"链接，进入搜索 Skill 的界面。\\n\\n![](assets/image-20260310100331112.png)\\n\\n### 第三步：找到目标 Skill\\n\\n在搜索框中输入关键字\\"xiaohongshu\\"，找到名字为\\"Xiaohongshu (小红书) Automation\\"的 Skill。\\n\\n![](assets/image-20260310100437311.png)\\n\\n### 第四步：查看 Skill 详情\\n\\n点击进入该 Skill 的详情页面，可以查看 Skill 的功能描述、使用说明和版本信息等。\\n\\n![](assets/image-20260310100522855.png)\\n\\n### 第五步：复制 Skill 标识符\\n\\n在浏览器的地址栏上直接复制 Skill 的名称\\"xiaohongshu-mcp\\"，这个标识符用于后续的安装和调用。\\n\\n![](assets/image-20260310100553812.png)\\n\\n### 第六步：在 OpenClaw 中安装 Skill\\n\\n回到 OpenClaw 的聊天窗口中，输入以下指令开始安装和使用 Skill：\\n\\n> 请安装和使用这个 skill \\"xiaohongshu-mcp\\"，帮我发布一篇关于冬日养生饮食的小红书文章。\\n\\nOpenClaw 会自动识别并下载该 Skill。\\n\\n![](assets/image-20260310100803670.png)\\n\\n### 第七步：完成登录配置\\n\\n首次使用该 Skill 时，需要进行登录配置。OpenClaw 会在对话窗口中显示提示信息，同时在电脑上弹出小红书的登录页面。\\n\\n![](assets/image-20260310101128909.png)\\n\\n![](assets/image-20260310101220267.png)\\n\\n### 第八步：完成账号登录\\n\\n在弹出的登录页面中完成账号登录操作。可以使用手机号、微信或微博等方式登录小红书账号。\\n\\n登录成功后，回到 OpenClaw 对话窗口，告知登录已完成，OpenClaw 将自动继续执行发帖操作。\\n\\n![](assets/image-20260310101414065.png)\\n\\n### 第九步：等待执行完成\\n\\nOpenClaw 会根据你提供的主题自动生成小红书文章内容，并执行发布操作。这个过程可能需要几秒钟到几分钟的时间，请耐心等待。\\n\\n执行完成后，对话窗口将显示执行结果提示，告知文章是否成功发布。\\n\\n![](assets/image-20260310101801451.png)\\n\\n### 第十步：确认发布结果\\n\\n切换到小红书页面，查看个人主页，确认帖子是否已成功发布。\\n\\n![](assets/image-20260310101949649.png)\\n\\n### 第十一步：后续使用\\n\\n后续再次执行小红书发布任务时，由于已完成登录配置，OpenClaw 将直接执行发帖操作，无需重复登录。\\n\\n只需在 OpenClaw 中输入发布指令，即可快速完成文章发布。\\n\\n![](assets/image-20260310102040615.png)\\n\\n## 使用技巧\\n\\n### 自定义内容\\n\\n你可以在指令中指定更具体的内容要求，例如：\\n\\n> 请使用 skill \\"xiaohongshu-mcp\\" 帮我发布一篇关于春季护肤的小红书笔记，内容要包含护肤步骤和推荐产品，风格要轻松活泼。\\n\\n### 批量发布\\n\\n可以一次性发布多篇内容，OpenClaw 会依次执行发布操作，确保每篇文章都成功发布后再继续下一篇。\\n\\n### 定时发布\\n\\n结合 OpenClaw 的定时任务功能，可以设置定时发布，让文章在指定时间自动发布，提高发布效率。\\n\\n\\n\\n## 总结\\n\\n通过 OpenClaw 的 MCP 服务对接功能，用户可以轻松实现小红书的自动发帖操作，大大提高了内容发布的效率。整个流程简单直观，无需复杂的技术配置，只需几个步骤即可完成从安装到发布的全过程。\\n\\n使用这种方式，内容创作者可以将更多精力投入到内容创作本身，而不是重复性的发布操作，让自动化工具为你的内容创作赋能。"}'),d={name:"AI人工智能/用 OpenClaw 实现小红书自动发帖/用OpenClaw实现小红书自动发帖.md"};function C(w,a,_,q,O,S){return n(),e("div",null,[...a[0]||(a[0]=[i("",61)])])}const f=l(d,[["render",C]]);export{x as __pageData,f as default};
